def _as_tuple(arr):
    """Return a Python tuple, matching SWIG's std::vector<T> exposure.

    Accepts numpy arrays, lists, or anything iterable; ``tolist`` is preferred
    on numpy arrays so individual elements come out as native Python scalars
    (matching upstream behaviour where a ``std::vector<int>`` becomes a tuple
    of Python ints, not numpy.int32).
    """
    if arr is None:
        return ()
    if hasattr(arr, "tolist"):
        return tuple(arr.tolist())
    return tuple(arr)


