def _not_yet(name: str):
    def _stub(*args, **kwargs):
        raise NotImplementedError(
            f"ifcopenshell.geom.{name} is not yet wired against the autogen C ABI"
        )

    _stub.__name__ = name
    return _stub


create_shape = None  # type: ignore[assignment]  # populated below
map_shape = None  # type: ignore[assignment]


def _instance_handle(inst):
    """Return a generated C-API handle for an entity_instance."""
    if inst is None:
        return None
    h = getattr(inst, "_handle", None)
    if h is None:
        h = getattr(getattr(inst, "wrapped_data", None), "_handle", None)
    if h is None:
        raise TypeError(f"create_shape: expected entity_instance, got {type(inst).__name__}")
    return h


def _result_geometry_type(settings_obj):
    """Resolve which element-geometry kind ``create_shape`` will return,
    based on the ``iterator-output`` setting on ``settings_obj``."""
    try:
        v = settings_obj.get("iterator-output")
    except Exception:
        v = NATIVE
    if v == TRIANGULATED:
        return TriangulationElement
    if v == SERIALIZED:
        return SerializedElement
    return BRepElement


def create_shape(
    settings_obj,
    inst,
    repr=None,  # noqa: A002 - mirrors upstream signature
    geometry_library: GEOMETRY_LIBRARY = "opencascade",
):
    """Compute geometry for ``inst`` (and optionally ``repr``).

    Returns either a fully-typed :class:`Element` subclass (when ``inst`` is
    an ``IfcProduct``) or just the geometry payload (``Triangulation`` /
    ``BRepRepresentation`` / ``Serialization``) when ``inst`` is a raw
    representation, item, or profile - matching the upstream SWIG
    behaviour.
    """
    if not isinstance(settings_obj, settings):
        raise TypeError("create_shape: settings argument must be ifcopenshell.geom.settings")

    try:
        is_placement = bool(inst.is_a("IfcObjectPlacement") or inst.is_a("IfcPlacement"))
    except Exception:
        is_placement = False
    if is_placement:
        from ifcopenshell.util.placement import get_local_placement
        from ifcopenshell.util.unit import calculate_unit_scale

        matrix = get_local_placement(inst).copy()
        if not settings_obj.get("convert-back-units"):
            file_obj = getattr(inst, "_file", None)
            if file_obj is not None:
                matrix[0:3, 3] *= calculate_unit_scale(file_obj)
        return PlacementTransformation(matrix)

    inst_h = _instance_handle(inst)
    repr_h = _instance_handle(repr) if repr is not None else None
    out = _capi.create_shape(
        settings_obj._h,
        inst_h,
        repr_h,
        geometry_library or "opencascade",
    )

    cls = _result_geometry_type(settings_obj)
    elem = cls.__new__(cls)
    _OwnedHandle.__init__(elem, out)

    is_product = False
    try:
        is_product = bool(inst.is_a("IfcProduct"))
    except Exception:
        is_product = False
    if is_product:
        return wrap_shape_creation(settings_obj, elem)
    geom = elem.geometry
    geom._element_owner = elem
    return wrap_shape_creation(settings_obj, geom)


def map_shape(settings_obj, inst):
    """Map ``inst`` to a taxonomy item (``ifcopenshell_geom_taxonomy_item_t``)."""
    if not isinstance(settings_obj, settings):
        raise TypeError("map_shape: settings argument must be ifcopenshell.geom.settings")
    inst_h = _instance_handle(inst)
    out = _capi.map_shape(settings_obj._h, inst_h)
    return TaxonomyItem(out)


class TaxonomyItem(_OwnedHandle):
    """Opaque wrapper over ``ifcopenshell_geom_taxonomy_item_t``."""

    _destroy_fn_name = "taxonomy_item_destroy"
iterate = None  # type: ignore[assignment]  # populated below
consume_iterator = None  # type: ignore[assignment]
make_shape_function = None  # type: ignore[assignment]  # populated below
serialise = None  # type: ignore[assignment]
tesselate = None  # type: ignore[assignment]


def _file_native_ptr(file_or_filename):
    """Resolve ``file_or_filename`` to a native file handle and
    return ``(handle, owning_file)``.

    The owning file is returned so callers can keep it alive for the
    lifetime of the iterator (the C iterator borrows from the file).
    """
    import ifcopenshell as _io

    if isinstance(file_or_filename, str):
        f = _io.open(file_or_filename)
    else:
        f = file_or_filename
    handle = getattr(f, "_handle", None)
    if handle is None:
        handle = getattr(getattr(f, "wrapped_data", None), "_handle", None)
    if handle is None:
        raise TypeError(
            f"iterate: expected ifcopenshell.file or path, got {type(file_or_filename).__name__}"
        )
    return handle, f


class iterator:
    """Iterator over geometric representations in an IFC file.

    Wraps the native ``ifcopenshell_geom_iterator_t`` and mirrors the
    upstream ``ifcopenshell.geom.iterator`` API so consumers can call
    :meth:`initialize`, :meth:`next`, :meth:`get`, :meth:`progress`, and
    iterate the instance directly.
    """

    def __init__(
        self,
        settings_obj: settings,
        file_or_filename,
        num_threads: int = 1,
        include=None,
        exclude=None,
        geometry_library: GEOMETRY_LIBRARY = "opencascade",
    ):
        if not isinstance(settings_obj, settings):
            raise TypeError("iterator: settings argument must be ifcopenshell.geom.settings")
        if include is not None and exclude is not None:
            raise ValueError("include and exclude cannot be specified simultaneously")

        self.settings = settings_obj
        file_ptr, self.file = _file_native_ptr(file_or_filename)

        gl = geometry_library or "opencascade"

        if include is None and exclude is None:
            out = _capi.create_iterator(
                gl, settings_obj._h, file_ptr, int(num_threads),
            )
        else:
            spec = include if exclude is None else exclude
            include_flag = include is not None
            spec_list = list(spec)
            entity_types = {type(x).__name__ for x in spec_list}
            if entity_types == {"entity_instance"}:
                if not all(x.is_a("IfcProduct") for x in spec_list):
                    raise ValueError(
                        "include/exclude must be aggregates of IfcProduct entity_instance values"
                    )
                ids = [x.id() for x in spec_list]
                out = _capi.create_iterator_with_include_exclude_id(
                    gl, settings_obj._h, file_ptr,
                    ids, bool(include_flag), int(num_threads),
                )
            else:
                str_list = [str(x) for x in spec_list]
                out = _capi.create_iterator_with_include_exclude(
                    gl, settings_obj._h, file_ptr,
                    str_list, bool(include_flag), int(num_threads),
                )

        self._h = out

    def __del__(self):
        try:
            if getattr(self, "_h", None):
                _capi.iterator_destroy(self._h)
                self._h = None
        except Exception:
            pass

    def initialize(self) -> bool:
        return bool(_capi.iterator_initialize(self._h))

    def next(self) -> bool:
        return bool(_capi.iterator_next(self._h))

    def progress(self) -> int:
        return int(_capi.iterator_progress(self._h))

    def compute_bounds(self, with_geometry: bool = False) -> None:
        _capi.iterator_compute_bounds(self._h, bool(with_geometry))

    def unit_magnitude(self) -> float:
        return float(_capi.iterator_unit_magnitude(self._h))

    def unit_name(self) -> str:
        return _capi.iterator_unit_name(self._h) or ""

    def get_log(self) -> str:
        return _capi.iterator_get_log(self._h) or ""

    def had_error_processing_elements(self) -> bool:
        return bool(_capi.iterator_had_error_processing_elements(self._h))

    def get(self):
        """Return the current element as the appropriate :class:`Element`
        subclass, mirroring the iterator-output configuration."""
        cls = _result_geometry_type(self.settings)
        if cls is TriangulationElement:
            out = _capi.iterator_get_as_triangulation_element(self._h)
        elif cls is SerializedElement:
            out = _capi.iterator_get_as_serialized_element(self._h)
        else:
            out = _capi.iterator_get_as_brep_element(self._h)
        if not out:
            raise RuntimeError(_last_error("Failed to read iterator element"))
        elem = cls.__new__(cls)
        _OwnedHandle.__init__(elem, out)
        elem._destroy_fn_name = None
        return wrap_shape_creation(self.settings, elem)

    def get_native(self):
        """Return the current element as a :class:`BRepElement` regardless
        of the iterator-output setting."""
        out = _capi.iterator_get_native(self._h)
        if not out:
            return None
        elem = BRepElement.__new__(BRepElement)
        _OwnedHandle.__init__(elem, out)
        elem._destroy_fn_name = None
        return elem

    def __iter__(self):
        if self.initialize():
            while True:
                yield self.get()
                if not self.next():
                    break


def consume_iterator(it: iterator, with_progress: bool = False):
    """Drive ``it`` to completion, yielding each element (optionally with
    its progress percentage)."""
    if it.initialize():
        while True:
            if with_progress:
                yield it.progress(), it.get()
            else:
                yield it.get()
            if not it.next():
                break


def iterate(
    settings_obj: settings,
    file_or_filename,
    num_threads: int = 1,
    include=None,
    exclude=None,
    *,
    with_progress: bool = False,
    cache=None,
    serializer_settings=None,
    geometry_library: GEOMETRY_LIBRARY = "opencascade",
):
    """Yield geometry from ``file_or_filename`` element by element.

    The ``cache`` and ``serializer_settings`` parameters are accepted for
    signature parity with upstream but are not yet wired against the
    autogen ABI; passing a non-None ``cache`` raises
    :class:`NotImplementedError`.
    """
    if cache is not None:
        if serializer_settings is None:
            raise ValueError(
                "iterate(): serializer_settings must be provided when cache is set"
            )
        hdf5_cache = serializers.hdf5(cache, settings_obj, serializer_settings)
    else:
        hdf5_cache = None
    it = iterator(
        settings_obj, file_or_filename, num_threads, include, exclude, geometry_library
    )
    if hdf5_cache is not None:
        it._cache_anchor = hdf5_cache  # type: ignore[attr-defined]
    yield from consume_iterator(it, with_progress=with_progress)



# ---------------------------------------------------------------------------
# Tree (spatial query / clash detection / ray intersection).
# ---------------------------------------------------------------------------


# Mirrors ``ifcopenshell::geometry::clash::ClashType`` enum order.
CLASH_TYPE_ITEMS = ("protrusion", "pierce", "collision", "clearance")


def _last_error(prefix: str) -> str:
    err = _capi.last_error_message()
    msg = err if err else "Unknown error"
    return f"{prefix}: {msg}"


def _instance_list_from(items):
    """Build a native ``ifcopenshell_parse_instance_list_t`` from a
    Python iterable of :class:`entity_instance`. Caller owns the returned
    handle and must destroy it with ``instance_list_destroy``."""
    handles = [_instance_handle(x) for x in items]
    return _capi.instance_list_create_from_handles(handles)


def _instance_list_to_python(list_handle) -> list:
    """Consume an ``ifcopenshell_parse_instance_list_t`` (taking
    ownership) and return the contained instances as Python
    ``entity_instance`` objects."""
    try:
        n = _capi.instance_list_size(list_handle)
        result = []
        for i in range(n):
            inst = _capi.instance_list_get(list_handle, i)
            if inst:
                result.append(_wrap_product_instance(inst))
        return result
    finally:
        _capi.instance_list_destroy(list_handle)


class clash:
    """Lightweight Python view over an
    ``ifcopenshell_geom_tree_clash_t`` handle."""

    __slots__ = ("_h", "a", "b", "clash_type", "distance", "p1", "p2")

    def __init__(self, h):
        self._h = h
        self.a = _wrap_product_instance(_capi.tree_clash_a(h))
        self.b = _wrap_product_instance(_capi.tree_clash_b(h))
        self.clash_type = int(_capi.tree_clash_type(h))
        self.distance = float(_capi.tree_clash_distance(h))
        self.p1 = tuple(take_double_list(_capi.tree_clash_p1(h)))
        self.p2 = tuple(take_double_list(_capi.tree_clash_p2(h)))

    def __del__(self):
        try:
            if self._h:
                _capi.tree_clash_destroy(self._h)
                self._h = None
        except Exception:
            pass


class ray_intersection:
    """View over ``ifcopenshell_geom_tree_ray_intersection_t``."""

    __slots__ = (
        "_h", "instance", "distance", "dot_product",
        "position", "normal", "ray_distance", "style_index",
    )

