class buffer(_OwnedHandle):
    """In-memory or filename-backed serializer output sink.

    Mirrors upstream ``ifcopenshell_wrapper.buffer`` - the C++ serializers
    accept a ``stream_or_filename`` polymorphic type which Python has to
    construct explicitly via this wrapper.
    """

    _destroy_fn_name = "buffer_destroy"

    def __init__(self, filename: str | None = None):
        if filename is None:
            out = _capi.create_buffer()
        else:
            out = _capi.create_buffer_from_filename(str(filename))
        super().__init__(out)

    def get_value(self) -> str:
        result = _capi.buffer_get_value(self._h)
        if result is None:
            raise RuntimeError(_last_error("buffer.get_value failed"))
        return result

    def is_ready(self) -> bool:
        return bool(_capi.buffer_is_ready(self._h))


def transform_string(value):
    """Convert ``str`` to a :class:`buffer`; pass ``buffer`` through.

    The C++ serializers accept a ``stream_or_filename`` value that in C++
    auto-constructs from a string. Python needs an explicit conversion -
    upstream calls this helper before forwarding to the constructor.
    """
    if isinstance(value, str):
        return buffer(value)
    return value


def _serializer_handle(s):
    """Coerce a :class:`buffer`/handle/None into a native handle."""
    if s is None:
        return None
    if isinstance(s, _OwnedHandle):
        return s._h
    raise TypeError(f"expected buffer/serializer handle, got {type(s).__name__}")


class _SerializerBase(_OwnedHandle):
    """Base for serializers exposing the (non-geometry) base API.

    Concrete subclasses wrap one of the ``ifcopenshell_geom_serializer_t``
    or ``ifcopenshell_geom_geometry_serializer_t`` handle types.
    """

    _writes_geometry = False  # subclasses override

    def __init__(self, h, *, _keep=()):
        super().__init__(h)
        self._keep = _keep  # anchor referenced files/buffers

    def _fn_prefix(self) -> str:
        return (
            "geometry_serializer_"
            if self._writes_geometry
            else "serializer_"
        )

    def _call(self, suffix, *args):
        fn = getattr(_capi, self._fn_prefix() + suffix)
        fn(self._h, *args)

    def writeHeader(self) -> None:
        self._call("write_header")

    write_header = writeHeader

    def finalize(self) -> None:
        self._call("finalize")

    def setFile(self, f) -> None:
        ptr, owner = _file_native_ptr(f)
        self._call("set_file", ptr)
        self._keep = (self._keep, owner)

    set_file = setFile

    def ready(self) -> bool:
        fn = getattr(_capi, self._fn_prefix() + "ready")
        return bool(fn(self._h))


class GeometrySerializer(_SerializerBase):
    """Wraps ``ifcopenshell_geom_geometry_serializer_t``.

    Used for serializers that write per-element geometry (obj, svg, gltf,
    collada, hdf5, ttl, iges, step).
    """

    _destroy_fn_name = "geometry_serializer_destroy"
    _writes_geometry = True

    def write(self, element) -> None:
        if isinstance(element, BRepElement):
            self._call("write_brep_element", element._h)
        elif isinstance(element, TriangulationElement):
            self._call("write_triangulation_element", element._h)
        else:
            raise TypeError(
                f"GeometrySerializer.write: expected BRepElement or "
                f"TriangulationElement, got {type(element).__name__}"
            )

    def isTesselated(self) -> bool:
        fn = getattr(_capi, "geometry_serializer_is_tesselated")
        return bool(fn(self._h))

    is_tesselated = isTesselated

    def setUnitNameAndMagnitude(self, name: str, magnitude: float) -> None:
        self._call(
            "set_unit_name_and_magnitude",
            str(name),
            float(magnitude),
        )

    set_unit_name_and_magnitude = setUnitNameAndMagnitude


class Serializer(_SerializerBase):
    """Wraps ``ifcopenshell_geom_serializer_t`` (xml/json/rocksdb)."""

    _destroy_fn_name = "serializer_destroy"
    _writes_geometry = False


def _make_geometry_serializer(format, output, output_temp, geometry_settings, ser_settings):
    """Create a plugin serializer through an explicit path or stream API."""
    if isinstance(output, str) and isinstance(output_temp, str):
        out = _capi.create_geometry_serializer_by_path(
            format,
            output,
            output_temp,
            _serializer_handle(geometry_settings),
            _serializer_handle(ser_settings),
        )
        keep = (geometry_settings, ser_settings)
    else:
        output = transform_string(output)
        output_temp = transform_string(output_temp)
        out = _capi.create_geometry_serializer_by_stream(
            format,
            _serializer_handle(output),
            _serializer_handle(output_temp),
            _serializer_handle(geometry_settings),
            _serializer_handle(ser_settings),
        )
        keep = (output, output_temp, geometry_settings, ser_settings)
    return GeometrySerializer(out, _keep=keep)


def _make_filename_serializer(format, filename, geometry_settings, ser_settings):
    """Create a filename-backed :class:`GeometrySerializer`."""
    out = _capi.create_geometry_serializer_by_path(
        format,
        str(filename),
        "",
        _serializer_handle(geometry_settings),
        _serializer_handle(ser_settings),
    )
    return GeometrySerializer(out, _keep=(geometry_settings, ser_settings))


def _make_file_serializer(create_fn_name, file_or_filename, output_filename):
    """Create a base :class:`Serializer` (xml/json/rocksdb) bound to a file."""
    ptr, owner = _file_native_ptr(file_or_filename)
    fn = getattr(_capi, create_fn_name)
    out = fn(ptr, str(output_filename))
    return Serializer(out, _keep=(owner,))


class serializers:
    """Factory namespace for all output serializers.

    Mirrors upstream ``ifcopenshell.geom.serializers``. The C++ serializers
    accept a ``stream_or_filename`` value which Python represents as a
    :class:`buffer`; ``str`` arguments to the buffer-backed factories are
    converted automatically via :func:`transform_string`.
    """

    buffer = buffer

    @staticmethod
    def obj(out_filename, mtl_filename, geometry_settings, settings):
        return _make_geometry_serializer("obj", mtl_filename, out_filename, geometry_settings, settings)

    @staticmethod
    def svg(out_filename, geometry_settings, settings):
        return _make_geometry_serializer("svg", out_filename, out_filename, geometry_settings, settings)

    @staticmethod
    def ttl(out_filename, geometry_settings, settings):
        return _make_geometry_serializer("ttl", out_filename, out_filename, geometry_settings, settings)

    @staticmethod
    def gltf(out_filename, geometry_settings, settings):
        return _make_filename_serializer(
            "glb",
            out_filename, geometry_settings, settings,
        )

    @staticmethod
    def iges(out_filename, geometry_settings, settings):
        return _make_filename_serializer(
            "igs",
            out_filename, geometry_settings, settings,
        )

    @staticmethod
    def step(out_filename, geometry_settings, settings):
        return _make_filename_serializer(
            "stp",
            out_filename, geometry_settings, settings,
        )

    @staticmethod
    def collada(out_filename, geometry_settings, settings):
        return _make_filename_serializer(
            "dae",
            out_filename, geometry_settings, settings,
        )

    @staticmethod
    def hdf5(out_filename, geometry_settings, settings):
        return _make_filename_serializer(
            "hdf5",
            out_filename, geometry_settings, settings,
        )

    @staticmethod
    def xml(file_or_filename, out_filename):
        return _make_file_serializer(
            "create_xml_serializer",
            file_or_filename, out_filename,
        )

    @staticmethod
    def json(file_or_filename, out_filename):
        return _make_file_serializer(
            "create_json_serializer",
            file_or_filename, out_filename,
        )

    @staticmethod
    def rocksdb(file_or_filename, rocksdb_filename):
        if not isinstance(file_or_filename, (str, bytes, os.PathLike)):
            raise TypeError("rocksdb serializer requires an input filename")
        return serializers.rocksdb_streaming(file_or_filename, rocksdb_filename)

    @staticmethod
    def rocksdb_streaming(input_filename, rocksdb_filename, stream: bool = True):
        out = _capi.create_rocksdb_serializer_streaming(
            str(input_filename),
            str(rocksdb_filename),
        )
        return Serializer(out)

    @classmethod
    def guess_from_extension(cls, filepath: str):
        ext = filepath.rsplit(".", 1)[-1].lower()
        mapping = {
            "glb": "gltf",
            "gltf": "gltf",
            "hdf": "hdf5",
            "h5": "hdf5",
            "hdf5": "hdf5",
            "obj": "obj",
            "svg": "svg",
            "ttl": "ttl",
            "xml": "xml",
            "dae": "collada",
            "iges": "iges",
            "igs": "iges",
            "stp": "step",
            "step": "step",
            "json": "json",
        }
        name = mapping.get(ext)
        if not name:
            raise ValueError(f"No serializer available for .{ext} file")
        return getattr(cls, name)


def _schema_name_of(inst) -> str:
    """Return the schema name (e.g. ``"IFC4"``) owning ``inst``."""
    f = getattr(inst, "wrapped_data", None)
    if f is not None and hasattr(f, "file"):
        return f.file.schema
    f = getattr(inst, "file", None)
    if f is not None and hasattr(f, "schema"):
        return f.schema
    raise TypeError(
        f"_schema_name_of: cannot resolve schema for {type(inst).__name__}"
    )


def _wrap_serialise_result(h):
    """Promote a returned ``ifcopenshell_instance_t`` to an
    :class:`entity_instance` (or ``None``)."""
    if not h:
        return None
    from ifcopenshell.entity_instance import entity_instance
    return entity_instance(h)


def serialise(schema, string_or_shape, advanced: bool = True):
    """STEP-serialise ``string_or_shape`` against ``schema``.

    Wraps :c:func:`ifcopenshell_geom_serialise`. Accepts an OCC
    ``TopoDS_Shape`` only when OCC is available (matches upstream
    semantics).
    """
    if has_occ:
        try:
            from OCC.Core import TopoDS  # type: ignore[import-not-found]
            if isinstance(string_or_shape, TopoDS.TopoDS_Shape):
                from . import occ_utils as _utils  # type: ignore[import-not-found]
                string_or_shape = _utils.serialize_shape(string_or_shape)
        except ImportError:
            pass
    out = _capi.serialise(
        str(schema),
        str(string_or_shape),
        bool(advanced),
    )
    return _wrap_serialise_result(out)


def tesselate(schema, string_or_shape, deflection: float):
    """Tesselate ``string_or_shape`` against ``schema`` at ``deflection``.

    Wraps :c:func:`ifcopenshell_geom_tesselate`.
    """
    if has_occ:
        try:
            from OCC.Core import TopoDS  # type: ignore[import-not-found]
            if isinstance(string_or_shape, TopoDS.TopoDS_Shape):
                from . import occ_utils as _utils  # type: ignore[import-not-found]
                string_or_shape = _utils.serialize_shape(string_or_shape)
        except ImportError:
            pass
    out = _capi.tesselate(
        str(schema),
        str(string_or_shape),
        float(deflection),
    )
    return _wrap_serialise_result(out)


def make_shape_function(fn):
    """Adapt an underlying ``serialise``/``tesselate``-style function
    so that callers may pass either a string or (when OCC is available)
    a ``TopoDS_Shape``.

    The wrapped function already accepts both forms - this exists for
    upstream API parity (``serialise``/``tesselate`` are exposed as the
    result of ``make_shape_function(...)`` in legacy code).
    """
    return fn


